// Deduplication + warmup/test filtering using n8n workflow static data.
// On first run, records all existing replies without notifying (avoids Slack flood).
// On subsequent runs, only passes through NEW replies that are REAL campaign replies.
// Filters out: warmup emails, test emails, outgoing emails, and non-campaign replies.

const staticData = $getWorkflowStaticData('global');

// Handle both array responses and { data: [...] } wrapper
const inputItems = $input.all();
let replies = [];

if (inputItems.length === 1 && Array.isArray(inputItems[0].json?.data)) {
  replies = inputItems[0].json.data;
} else if (inputItems.length === 1 && Array.isArray(inputItems[0].json)) {
  replies = inputItems[0].json;
} else {
  replies = inputItems.map(item => item.json);
}

// Filter out warmup, test, and non-campaign replies BEFORE dedup
const realReplies = replies.filter(reply => {
  // Must be tied to a campaign (warmup/test emails have campaign_id: null)
  if (!reply.campaign_id) return false;
  // Must be tied to a lead (warmup emails have lead_id: null)
  if (!reply.lead_id) return false;
  // Must NOT be an outgoing email (we want incoming replies from prospects)
  if (reply.type === 'Outgoing Email') return false;
  // Skip test emails
  if (reply.subject && reply.subject.startsWith('[test]')) return false;
  // Skip automated replies
  if (reply.automated_reply) return false;
  return true;
});

// First run: initialize state, send nothing
if (!staticData.initialized) {
  staticData.initialized = true;
  if (realReplies.length > 0) {
    const timestamps = realReplies
      .map(r => r.created_at || r.received_at || r.date || '')
      .filter(Boolean)
      .sort();
    staticData.lastSeenTimestamp = timestamps.length > 0 ? timestamps[timestamps.length - 1] : new Date().toISOString();
    staticData.seenReplyIds = realReplies.map(r => r.id).filter(Boolean).slice(-500);
  } else {
    staticData.lastSeenTimestamp = new Date().toISOString();
    staticData.seenReplyIds = [];
  }
  return [];
}

const lastSeenTimestamp = staticData.lastSeenTimestamp || '1970-01-01T00:00:00Z';
const seenIds = new Set(staticData.seenReplyIds || []);

// Filter to only new replies
const newReplies = realReplies.filter(reply => {
  const replyId = reply.id;
  const replyTimestamp = reply.created_at || reply.received_at || reply.date || '';
  return replyId && !seenIds.has(replyId) && replyTimestamp > lastSeenTimestamp;
});

// Update high-water mark
if (newReplies.length > 0) {
  const allTimestamps = newReplies
    .map(r => r.created_at || r.received_at || r.date || '')
    .filter(Boolean)
    .sort();
  if (allTimestamps.length > 0) {
    staticData.lastSeenTimestamp = allTimestamps[allTimestamps.length - 1];
  }
  const newIds = newReplies.map(r => r.id).filter(Boolean);
  staticData.seenReplyIds = [...(staticData.seenReplyIds || []), ...newIds].slice(-500);
}

// Normalize each reply into a consistent shape for downstream nodes
return newReplies.map(reply => {
  const lead = reply.lead || {};
  const campaign = reply.campaign || {};
  const body = reply.html_body || reply.text_body || reply.body || reply.message || '';
  const plainBody = reply.text_body || body.replace(/<[^>]*>/g, '');

  return {
    json: {
      reply_id: reply.id,
      lead_name: [lead.first_name || reply.from_name || '', lead.last_name || ''].filter(Boolean).join(' ') || reply.from_name || 'Unknown',
      lead_email: lead.email || reply.from_email_address || 'N/A',
      lead_company: lead.company || lead.company_name || 'N/A',
      campaign_name: campaign.name || reply.campaign_name || 'N/A',
      campaign_id: reply.campaign_id || campaign.id || '',
      subject: reply.subject || '',
      reply_snippet: plainBody.length > 300 ? plainBody.substring(0, 300) + '...' : plainBody,
      reply_full: plainBody,
      received_at: reply.date_received || reply.created_at || ''
    }
  };
});
